package ngl.relay.app; import android.app.*;import android.os.*;import android.text.InputType;import android.widget.*;
public final class SettingsActivity extends Activity { public void onCreate(Bundle b){super.onCreate(b);ScrollView sv=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);TextView h=new TextView(this);h.setText("Cognition nodes\nNodes are interchangeable. Enable a slot, paste its API key, pick a model. Keys live in this device's app-private storage only. Any node you enable participates in all methodology stages.");root.addView(h);for(NodeRegistry.Slot s:NodeRegistry.KNOWN_NODES){TextView t=new TextView(this);t.setText(s.label+" — "+s.provider);root.addView(t);CheckBox e=new CheckBox(this);e.setText("Enabled (participates in stages)");e.setChecked(NodeRegistry.enabled(this,s.id));root.addView(e);EditText key=new EditText(this);key.setHint("API key (app-private storage, never in APK/artifacts)");key.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);key.setText(NodeRegistry.apiKey(this,s.id));root.addView(key);EditText model=new EditText(this);model.setHint("model id (default: "+s.defaultModel+")");model.setText(NodeRegistry.model(this,s.id));root.addView(model);EditText base=new EditText(this);base.setHint("endpoint base (default: "+s.defaultBase+")");base.setText(NodeRegistry.baseUrl(this,s.id));root.addView(base);Button save=new Button(this);save.setText("SAVE "+s.label.toUpperCase()+" SETTINGS");save.setOnClickListener(v->{NodeRegistry.setEnabled(this,s.id,e.isChecked());NodeRegistry.setApiKey(this,s.id,key.getText().toString());NodeRegistry.setModel(this,s.id,model.getText().toString());NodeRegistry.setBaseUrl(this,s.id,base.getText().toString());});root.addView(save);}sv.addView(root);setContentView(sv);} }
